'use strict';

async function legacySourceMetadata({verify}) {
  let legacyMetadataCases = 0;
  for (const version of ['2.3', '2.4']) for (const newline of ['\n', '\r\n']) {
    const wrap = body => ('INTERLIS ' + version + ';\nCONTRACTED MODEL F AT "x" VERSION "1" =\n' + body + '\nEND F.').replaceAll('\n', newline);
    await verify(wrap('!!@ fn.description="🦊";\n!!@ fn.param="url address";\n!!@ fn.param="prefix namespace";\n!!@ fn.return="First line\n!!@ second line";\nFUNCTION f(url:TEXT;prefix:TEXT):BOOLEAN;'), 'succeeded');
    await verify(wrap('!!@ label=one;label=two\nDOMAIN D=TEXT;'), 'rejected');
    await verify(wrap('!!@ fn.return="open\nFUNCTION f(url:TEXT):BOOLEAN;'), 'rejected');
    legacyMetadataCases += 3;
  }

  // L0A: nested delimiters must have the same validity on JVM and TeaVM.
  return legacyMetadataCases;
}

async function nestedComments({verify}) {
  let nestedCommentCases = 0;
  for (const version of ['2.3', '2.4']) {
    for (const [comment, expected] of [
      ['/* outer /* middle /* inner 😀 */ middle */ outer */', 'succeeded'],
      ['/* / // ** ***/', 'succeeded'],
      ['/* outer', 'rejected'],
      ['/* outer /* inner', 'rejected'],
      ['/* outer /* inner */', 'rejected']
    ]) {
      await verify(`INTERLIS ${version}; MODEL F AT "x" VERSION "1" =
!! prefix 😀\r\n${comment}\r\nTOPIC T = CLASS C = END C; END T; END F.`, expected);
      nestedCommentCases++;
    }
  }
  return nestedCommentCases;
}

async function metadataAnnotations({verify, verifySources}) {
  let metadataCases = 0;
  for (const version of ['2.3', '2.4']) {
    const wrap = body => `INTERLIS ${version}; CONTRACTED MODEL F AT "https://example.org" VERSION "1" = ${body} END F.`;
    const base = 'TOPIC Systems = CLASS CS EXTENDS INTERLIS.COORDSYSTEM = END CS; CLASS SS EXTENDS INTERLIS.SCALSYSTEM = END SS; END Systems; ';
    const basket = base + 'REFSYSTEM BASKET B ~ Systems OBJECTS OF CS: CH; ';
    const coord = 'DOMAIN Coord = COORD 0.00..100.00 [INTERLIS.m] {B.CH[1]},0.00..100.00 [INTERLIS.m] {B.CH[2]}, ROTATION 2 -> 1; ';
    const scalar = 'TOPIC Systems = CLASS SS EXTENDS INTERLIS.SCALSYSTEM = PARAMETER Unit (EXTENDED): NUMERIC [INTERLIS.LENGTH]; END SS; END Systems; REFSYSTEM BASKET B ~ Systems OBJECTS OF SS: S; DOMAIN N = 0..100 [INTERLIS.m] {B.S};';
    const geometry = 'DOMAIN Coord = COORD 0.00..100.00,0.00..100.00,0.00..100.00; ';
    const area = 'TOPIC T = CLASS A = kind: TEXT*10; area: AREA WITH (STRAIGHTS) VERTEX Coord WITHOUT OVERLAPS > 0.01; END A; VIEW V AREA INSPECTION OF edge~A->area; = left := THISAREA->kind; right := THATAREA->kind; END V; END T;';
    for (const [body, expected] of [
      [basket + coord, 'succeeded'],
      [basket + coord + 'DOMAIN Azimuth = 0.0000..399.9999 CIRCULAR <Coord>;', 'succeeded'],
      [basket + coord + 'DOMAIN Azimuth = 0.0000..399.9999 CIRCULAR [INTERLIS.rad] <Coord>;', 'succeeded'],
      [basket + coord + 'DOMAIN Azimuth = 0.0000..399.9999 CIRCULAR [INTERLIS.m] <Coord>;', 'rejected'],
      [basket + coord + 'DOMAIN Height = 0.00..10.00 [INTERLIS.m] <Coord[2]>;', 'succeeded'],
      [basket + coord.replace('CH[2]', 'CH[4]'), 'rejected'],
      [basket + coord.replace('CH[2]', 'CH[0]'), 'rejected'],
      [basket + coord.replace('B.CH[2]', 'Wrong.CH[2]'), 'rejected'],
      [basket + coord.replace('2 -> 1', '3 -> 1'), 'rejected'],
      [basket + coord.replace(', ROTATION 2 -> 1', '') + 'DOMAIN Wrong = 0..10 <Coord>;', 'rejected'],
      [base + 'REFSYSTEM BASKET B ~ Systems OBJECTS OF CS: CH,CH;', 'rejected'],
      [base + 'REFSYSTEM BASKET B (FINAL) ~ Systems; REFSYSTEM BASKET C EXTENDS B ~ Systems;', 'rejected'],
      [base + 'REFSYSTEM BASKET B EXTENDS C ~ Systems; REFSYSTEM BASKET C EXTENDS B ~ Systems;', 'rejected'],
      [base + 'REFSYSTEM BASKET B ~ Systems OBJECTS OF SS: S; REFSYSTEM BASKET C EXTENDS B ~ Systems; DOMAIN N = 0..100 {C.S};', 'succeeded'],
      [scalar, 'succeeded'],
      [scalar.replace('[INTERLIS.m]', '[INTERLIS.s]'), 'rejected'],
      [scalar.replace('[INTERLIS.m]', ''), 'rejected'],
      [scalar.replace('Unit (EXTENDED)', 'Other'), 'rejected'],
      [scalar.replace('Unit (EXTENDED)', 'Unit'), 'rejected'],
      [geometry + area, 'succeeded'],
      [geometry + area.replace('left :=', 'ALL OF edge; left :='), 'rejected'],
      [geometry + 'STRUCTURE Attrs = label: TEXT; END Attrs; TOPIC T = CLASS A = area: SURFACE WITH (STRAIGHTS) VERTEX Coord WITHOUT OVERLAPS > 0.01 LINE ATTRIBUTES Attrs; END A; VIEW V INSPECTION OF edge~A->area; = ALL OF edge; END V; END T;', version === '2.3' ? 'succeeded' : 'rejected'],
      [geometry + 'STRUCTURE S EXTENDS INTERLIS.LineSegment = x: TEXT; END S; LINE FORM Curve: S; TOPIC T = CLASS A = line: POLYLINE WITH (Curve) VERTEX Coord; END A; VIEW V INSPECTION OF line~A->line; = END V; END T;', 'succeeded'],
    ]) { await verify(wrap(body), expected); metadataCases++; }
    const original = wrap(basket + coord).replace('MODEL F', 'MODEL Original').replace('END F.', 'END Original.');
    const translated = wrap((basket + coord).replaceAll('Systems', 'Systemes').replaceAll('CS', 'Systeme').replace('B ~', 'Panier ~').replaceAll('B.CH', 'Panier.CH'))
      .replace(`INTERLIS ${version}; `, '').replace('VERSION "1" =', 'VERSION "1" TRANSLATION OF Original ["1"] =');
    for (const [text, expected] of [[original + translated, 'succeeded'], [original + translated.replaceAll('CH', 'Autre'), 'rejected'], [original + translated.replace('CH[2]', 'CH[1]'), 'rejected']]) {
      await verify(text, expected); metadataCases++;
    }
    for (const reverse of [false,true]) {
      await verifySources([
        {sourceId: reverse ? 'memory:/z-meta.ili' : 'memory:/a-meta.ili', text: wrap(basket).replace('MODEL F', 'MODEL Base').replace('END F.', 'END Base.')},
        {sourceId: reverse ? 'memory:/a-use.ili' : 'memory:/z-use.ili', text: wrap('IMPORTS Base; ' + coord.replaceAll('B.CH', 'Base.B.CH'))}
      ], 'succeeded'); metadataCases++;
    }
  }
  return metadataCases;
}

